begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir fixtures/costing-salon.inc
create function pg_temp.saas() returns jsonb language sql volatile as $$
 select public.saas_snapshot('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011');
$$;
create function pg_temp.change_saas(state text,plan uuid default 'f7000000-0000-4000-8000-000000000002') returns jsonb language sql volatile as $$
 select app_private.saas_control('b4000000-0000-4000-8000-000000000001',jsonb_build_object('type','SUBSCRIPTION','expected_version',
  (select version from app_private.saas_accounts where organization_id='b4000000-0000-4000-8000-000000000001'),'plan_version_id',plan,'status',state),
  'TEST_OPERATOR','Explicit synthetic subscription state',gen_random_uuid());
$$;
reset role;
select is((select count(*) from app_private.saas_accounts where organization_id='b4000000-0000-4000-8000-000000000001'),1::bigint,'one account per original organization');
set local role authenticated;
select is(pg_temp.saas()#>>'{data,status}','ACTIVE','configured neutral fixture active');
select is(pg_temp.saas()#>>'{data,management_allowed}','false','location owner does not acquire organization billing governance');
select is(pg_temp.saas()#>>'{data,plan}',null::text,'plan governance hidden from location-only owner');
select throws_ok($$select app_private.saas_control('b4000000-0000-4000-8000-000000000001','{}','client','forged',gen_random_uuid())$$,'42501',null,'normal member cannot invoke platform control');
select throws_ok($$select * from app_private.saas_usage_events$$,'42501',null,'durable usage private to normal roles');
select throws_ok($$update app_private.saas_accounts set status='ACTIVE'$$,'42501',null,'Data API role cannot forge subscription status');
select is(public.saas_snapshot('b4000000-0000-4000-8000-000000000112','b4000000-0000-4000-8000-000000000012')->>'code','TENANT_CONTEXT_INVALID','cross-organization subscription denied with the existing context contract');
reset role;
update public.salon_memberships set location_id=null where id='b4000000-0000-4000-8000-000000000111';
set local role authenticated;
select is(pg_temp.saas()#>>'{data,management_allowed}','true','current organization-wide owner can inspect governance');
select is(pg_temp.saas()#>>'{data,plan,code}','PLAN_A','configured label is not an invented commercial tier');
select is((select count(*) from jsonb_array_elements(pg_temp.saas()#>'{data,entitlements}') e where e->>'creation_allowed'='true'),10::bigint,'active subscription enables configured capabilities');
select is(public.saas_operation('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011','{"type":"SUBSCRIPTION","status":"ACTIVE"}',gen_random_uuid())->>'code','VALIDATION_FAILED','tenant cannot submit authoritative subscription fields');
select ok(public.saas_operation('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011','{"type":"REQUEST_CHANGE","request_id":"f7000000-0000-4000-8000-000000000501","reason":"Request review of configured capabilities"}',gen_random_uuid()) ? 'data','neutral change request stores intent, not payment');
select ok(public.saas_operation('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011','{"type":"REQUEST_CHANGE","request_id":"f7000000-0000-4000-8000-000000000501","reason":"Request review of configured capabilities"}',gen_random_uuid()) ? 'data','same change request idempotent');
reset role;
select is((select count(*) from app_private.saas_change_requests),1::bigint,'request replay creates one immutable intent');
select ok(pg_temp.change_saas('SUSPENDED') ? 'data','actual platform suspension');
set local role authenticated;
select is(pg_temp.saas()#>>'{data,status}','SUSPENDED','fresh authoritative state replaces prior active view');
select is((select count(*) from jsonb_array_elements(pg_temp.saas()#>'{data,entitlements}') e where e->>'creation_allowed'='true'),0::bigint,'suspension disables new capabilities');
select ok(public.reporting_snapshot('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011','{}') ? 'data','historical reporting remains permitted after suspension');
select ok((select count(*) from public.color_plans)>0,'historical plans remain readable');
reset role;
select throws_ok($$select app_private.saas_require('b4000000-0000-4000-8000-000000000001','STOCK')$$,'P0001','SUBSCRIPTION_RESTRICTED','new premium work is blocked');
select ok(pg_temp.change_saas('ACTIVE') ? 'data','reactivation appends new state');
select is((select count(*) from app_private.saas_subscriptions where organization_id='b4000000-0000-4000-8000-000000000001'),3::bigint,'immutable subscription history includes bootstrap, suspension and reactivation');
select throws_ok($$update app_private.saas_subscriptions set status='ACTIVE'$$,'23514','IMMUTABLE_LIVE_HISTORY','commercial history cannot be overwritten');
select ok(app_private.saas_control('b4000000-0000-4000-8000-000000000001','{"type":"REBUILD_USAGE"}','TEST_OPERATOR','Rebuild golden source usage',gen_random_uuid()) ? 'data','usage counter rebuild uses durable events');
select is((select coalesce(sum(quantity),0) from app_private.saas_usage_counters where organization_id='b4000000-0000-4000-8000-000000000001' and category='ENGINE_EXECUTIONS'),
 (select coalesce(sum(quantity),0) from app_private.saas_usage_events where organization_id='b4000000-0000-4000-8000-000000000001' and category='ENGINE_EXECUTIONS'),'counter equals permanent successful source events');
select ok(not has_function_privilege('authenticated','app_private.saas_provider_event(text,text,text,text,jsonb,uuid)','execute'),'unsigned browser provider event cannot change subscription');
-- Real Storage RLS: registered evidence remains accessible; unknown quota,
-- foreign actors and revoked memberships cannot upload.
create function pg_temp.photo(n integer) returns text language plpgsql as $$declare path text;begin
 path:='b4000000-0000-4000-8000-000000000001/b4000000-0000-4000-8000-000000000803/b4000000-0000-4000-8000-000000000021/'||n;
 insert into public.live_photos values('b4000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000803',gen_random_uuid(),'BEFORE',path,'image/png','b4000000-0000-4000-8000-000000000021',statement_timestamp());return path;end$$;
select pg_temp.photo(1),pg_temp.photo(2),pg_temp.photo(3),pg_temp.photo(4);
set local role authenticated;
select is(public.saas_storage_access('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011','b4000000-0000-4000-8000-000000000001/b4000000-0000-4000-8000-000000000803/b4000000-0000-4000-8000-000000000021/1')#>>'{data,allowed}','true','explicit uncapped quota permits the validated proxy upload');
reset role;
select pg_temp.change_saas('SUSPENDED');
set local role authenticated;
select is(public.saas_storage_access('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011','b4000000-0000-4000-8000-000000000001/b4000000-0000-4000-8000-000000000803/b4000000-0000-4000-8000-000000000021/2')#>>'{data,allowed}','true','suspended running session can preserve safety evidence through validated proxy');
select is((select count(*) from storage.objects where bucket_id='live-technical'),0::bigint,'suspension never opens a direct read or signing bypass');
reset role;
-- Missing definitions are unknown, not unlimited. Downgrade retains excess.
select pg_temp.change_saas('ACTIVE');
select ok(pg_temp.cost_policy('f7000000-0000-4000-8000-000000000601','PERCENT_NET_OF_TAX',1000) ? 'data','configured plan permits an actual future commission policy');
create temporary table saas_new_plan(id uuid);grant select on saas_new_plan to authenticated;
insert into saas_new_plan select (app_private.saas_control('b4000000-0000-4000-8000-000000000001','{"type":"PLAN_VERSION","code":"PLAN_B","label":"PLAN_B","development_only":true,"expected_version":0,"entitlements":{},"quotas":{"LOCATIONS":0}}','TEST_OPERATOR','Synthetic explicit downgrade',gen_random_uuid())#>>'{data,id}')::uuid;
select pg_temp.change_saas('ACTIVE',(select id from saas_new_plan));
select throws_ok($$select app_private.saas_require('b4000000-0000-4000-8000-000000000001','STOCK')$$,'P0001','FEATURE_UNAVAILABLE','missing entitlement cannot enable new stock work');
select throws_ok($$insert into public.client_crm_actions values(gen_random_uuid(),'b4000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000011','b4000000-0000-4000-8000-000000000031','REBOOK','salon_appointment','e5000000-0000-4000-8000-000000000811','{}','OPEN',statement_timestamp(),null,1,statement_timestamp(),statement_timestamp(),'b4000000-0000-4000-8000-000000000021','b4000000-0000-4000-8000-000000000021')$$,'P0001','FEATURE_UNAVAILABLE','new CRM source cannot bypass missing entitlement');
select throws_ok($$select public.costing_operation('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011',jsonb_build_object('type','ASSIGN','mutation_id',gen_random_uuid(),'id',gen_random_uuid(),'staff_user_id','b4000000-0000-4000-8000-000000000021','policy_id','f7000000-0000-4000-8000-000000000601','scope','DEFAULT_SERVICE','service_id',null,'category',null,'effective_from',statement_timestamp(),'effective_until',null,'reason','Synthetic future assignment'),gen_random_uuid())$$,'P0001','FEATURE_UNAVAILABLE','future commission assignment requires configured entitlement');
select throws_ok($$select app_private.saas_quota('b4000000-0000-4000-8000-000000000001','ACTIVE_MEMBERS',1)$$,'P0001','QUOTA_UNKNOWN','missing member quota fails closed');
select throws_ok($$select app_private.saas_quota('b4000000-0000-4000-8000-000000000001','LOCATIONS',1)$$,'P0001','QUOTA_EXCEEDED','explicit zero limit blocks growth');
select is((select count(*) from public.locations where organization_id='b4000000-0000-4000-8000-000000000001'),1::bigint,'downgrade preserves existing over-limit location');
set local role authenticated;
select throws_ok($$insert into storage.objects(bucket_id,name) values('live-technical','b4000000-0000-4000-8000-000000000001/b4000000-0000-4000-8000-000000000803/b4000000-0000-4000-8000-000000000021/3')$$,'42501',null,'unknown storage quota denies actual registered upload');
select is(public.saas_storage_access('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011','b4000000-0000-4000-8000-000000000001/b4000000-0000-4000-8000-000000000803/b4000000-0000-4000-8000-000000000021/3')->>'code','QUOTA_UNKNOWN','upload error diagnostic retains unknown state');
reset role;
select pg_temp.change_saas('ACTIVE');
set local role authenticated;
select is((select count(*) from jsonb_array_elements(pg_temp.saas()#>'{data,entitlements}') e where e->>'creation_allowed'='true'),10::bigint,'upgrade re-enables configured features');
reset role;
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000022',true);
set local role authenticated;
select throws_ok($$insert into storage.objects(bucket_id,name) values('live-technical','b4000000-0000-4000-8000-000000000001/b4000000-0000-4000-8000-000000000803/b4000000-0000-4000-8000-000000000021/3')$$,'42501',null,'cross-tenant photo upload remains denied');
select is((select count(*) from storage.objects where bucket_id='live-technical'),0::bigint,'cross-tenant private evidence stays hidden');
reset role;
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000024',true);
set local role authenticated;
select is(public.saas_operation('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{"type":"REBUILD_USAGE"}',gen_random_uuid())->>'code','FORBIDDEN','enabled plan does not grant reception governance permission');
reset role;
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000021',true);
update public.salon_memberships set status='revoked',revoked_at=statement_timestamp() where id='b4000000-0000-4000-8000-000000000111';
set local role authenticated;
select throws_ok($$insert into storage.objects(bucket_id,name) values('live-technical','b4000000-0000-4000-8000-000000000001/b4000000-0000-4000-8000-000000000803/b4000000-0000-4000-8000-000000000021/4')$$,'42501',null,'revoked membership cannot upload even with enabled plan');
reset role;
update public.salon_memberships set status='active',revoked_at=null where id='b4000000-0000-4000-8000-000000000111';
select app_private.saas_control('b4000000-0000-4000-8000-000000000001',jsonb_build_object('type','SUBSCRIPTION','expected_version',(select version from app_private.saas_accounts where organization_id='b4000000-0000-4000-8000-000000000001'),'plan_version_id','f7000000-0000-4000-8000-000000000002','status','TRIAL','trial_end',statement_timestamp()+interval '0.1 second'),'TEST_OPERATOR','Explicit synthetic trial deadline',gen_random_uuid());
select pg_sleep(0.15);
set local role authenticated;
select is(pg_temp.saas()#>>'{data,status}','TRIAL_EXPIRED','server clock expires trial without client state authority');
select is(pg_temp.saas()#>>'{data,status}','TRIAL_EXPIRED','repeated expiry read stays stable');
reset role;
select is((select count(*) from app_private.saas_expiry_observations where organization_id='b4000000-0000-4000-8000-000000000001' and kind='TRIAL_ENDED'),1::bigint,'expiry observation is append-only and idempotent');
select is((select count(*) from public.audit_events where organization_id='b4000000-0000-4000-8000-000000000001' and action='saas.trial_ended'),1::bigint,'server deadline is audited once');
select app_private.saas_control('b4000000-0000-4000-8000-000000000001',jsonb_build_object('type','SUBSCRIPTION','expected_version',(select version from app_private.saas_accounts where organization_id='b4000000-0000-4000-8000-000000000001'),'plan_version_id','f7000000-0000-4000-8000-000000000002','status','TRIAL','trial_end',statement_timestamp()+interval '0.2 second','effective_until',statement_timestamp()+interval '0.1 second'),'TEST_OPERATOR','Explicit competing end deadlines',gen_random_uuid());
select pg_sleep(0.25);
set local role authenticated;
select is(pg_temp.saas()#>>'{data,status}','EXPIRED','subscription end takes precedence over trial end');
reset role;
select is((select count(*) from app_private.saas_expiry_observations where organization_id='b4000000-0000-4000-8000-000000000001' and kind='SUBSCRIPTION_ENDED'),1::bigint,'expiry audit follows authoritative end precedence');
select * from finish();
rollback;
